const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── ENUMS ────────────────────────────────────────────────────────────────────\n\nenum PlanoTipo {\n  BASICO\n  PROFISSIONAL\n  ENTERPRISE\n}\n\nenum StatusEmpresa {\n  ATIVA\n  SUSPENSA\n  CANCELADA\n}\n\n// ─── MULTIEMPRESA ─────────────────────────────────────────────────────────────\n\nmodel Empresa {\n  id            String        @id @default(cuid())\n  nome          String\n  slug          String        @unique\n  cnpj          String?       @unique\n  logo_url      String?\n  plano         PlanoTipo     @default(BASICO)\n  status        StatusEmpresa @default(ATIVA)\n  configuracoes Json          @default(\"{}\")\n  asaas_api_key String?\n  criado_em     DateTime      @default(now())\n  atualizado_em DateTime      @updatedAt\n\n  membros                   MembroEmpresa[]\n  perfis                    Perfil[]\n  convites                  ConviteEmpresa[]\n  convites_cliente          ConviteCliente[]\n  clientes                  Cliente[]\n  servicos                  Servico[]\n  leads                     Lead[]\n  propostas                 Proposta[]\n  contratos                 Contrato[]\n  projetos                  Projeto[]\n  documentos                Documento[]\n  pastas_documento          PastaDocumento[]\n  plano_contas              PlanoDeContas[]\n  contas_bancarias          ContaBancaria[]\n  transferencias_tesouraria TransferenciaTesouraria[]\n  boletos                   Boleto[]\n  recebiveis                Recebivel[]\n  contas_pagar              ContaPagar[]\n  fornecedores              Fornecedor[]\n  modelos_documento         ModeloDocumento[]\n  eventos                   Evento[]\n  registros_auditoria       RegistroAuditoria[]\n  notificacoes              Notificacao[]\n  notas_fiscais             NotaFiscal[]\n  diagnosticos              Diagnostico[]\n  etiquetas_tarefa          EtiquetaTarefa[]\n  aplicacoes_diagnostico    AplicacaoDiagnostico[]\n  etapas_crm                EtapaCrm[]\n  campanhas_diagnostico     CampanhaDiagnostico[]\n  centros_custo             CentroCusto[]\n  diagnostico_templates     DiagnosticoTemplate[]\n  assinaturas               Assinatura[]\n  campanhas_cupom           CampanhaCupom[]\n  reembolsos                Reembolso[]\n\n  @@map(\"empresas\")\n}\n\n// ─── USUÁRIOS (espelha auth.users do Supabase) ────────────────────────────────\n\nmodel Usuario {\n  id            String   @id // igual ao auth.users.id\n  nome          String\n  email         String   @unique\n  avatar_url    String?\n  criado_em     DateTime @default(now())\n  atualizado_em DateTime @updatedAt\n\n  membros                MembroEmpresa[]\n  convites               ConviteEmpresa[]\n  leads                  Lead[]\n  comentarios_crm        ComentarioCrm[]\n  propostas_criadas      Proposta[]\n  contratos_criados      Contrato[]\n  projetos_criados       Projeto[]\n  tarefas                Tarefa[]\n  documentos_criados     Documento[]\n  recebiveis_criados     Recebivel[]         @relation(\"RecebiveisCriados\")\n  contas_pagar_criadas   ContaPagar[]        @relation(\"ContasPagarCriadas\")\n  eventos_responsavel    Evento[]            @relation(\"EventosResponsavel\")\n  propostas_responsavel  Proposta[]          @relation(\"PropostasResponsavel\")\n  contratos_responsavel  Contrato[]          @relation(\"ContratosResponsavel\")\n  convites_cliente       ConviteCliente[]\n  comentarios_tarefa     ComentarioTarefa[]\n  anexos_tarefa          AnexoTarefa[]\n  atividades_tarefa      AtividadeTarefa[]\n  aprovacoes_solicitadas AprovacaoTarefa[]   @relation(\"AprovacaoSolicitante\")\n  aprovacoes_recebidas   AprovacaoTarefa[]   @relation(\"AprovacaoAprovador\")\n  tarefas_responsavel    TarefaResponsavel[]\n\n  @@map(\"usuarios\")\n}\n\n// ─── MEMBRO: relação usuário ↔ empresa ───────────────────────────────────────\n\nmodel MembroEmpresa {\n  id         String   @id @default(cuid())\n  usuario_id String\n  empresa_id String\n  perfil_id  String\n  ativo      Boolean  @default(true)\n  criado_em  DateTime @default(now())\n\n  usuario Usuario @relation(fields: [usuario_id], references: [id], onDelete: Cascade)\n  empresa Empresa @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  perfil  Perfil  @relation(fields: [perfil_id], references: [id])\n\n  @@unique([usuario_id, empresa_id])\n  @@map(\"membros_empresa\")\n}\n\n// ─── RBAC: PERFIS ─────────────────────────────────────────────────────────────\n\nmodel Perfil {\n  id         String   @id @default(cuid())\n  empresa_id String? // null = perfil padrão do sistema (não editável)\n  nome       String\n  descricao  String?\n  sistema    Boolean  @default(false)\n  criado_em  DateTime @default(now())\n\n  empresa    Empresa?          @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  membros    MembroEmpresa[]\n  permissoes PerfilPermissao[]\n\n  @@unique([empresa_id, nome])\n  @@map(\"perfis\")\n}\n\n// ─── RBAC: PERMISSÕES ─────────────────────────────────────────────────────────\n\nmodel Permissao {\n  id        String  @id @default(cuid())\n  recurso   String // ex: \"clientes\", \"propostas\", \"contratos\"\n  acao      String // ex: \"ver\", \"criar\", \"editar\", \"excluir\"\n  descricao String?\n\n  perfis PerfilPermissao[]\n\n  @@unique([recurso, acao])\n  @@map(\"permissoes\")\n}\n\n// ─── RBAC: PERFIL ↔ PERMISSÃO ────────────────────────────────────────────────\n\nmodel PerfilPermissao {\n  perfil_id    String\n  permissao_id String\n\n  perfil    Perfil    @relation(fields: [perfil_id], references: [id], onDelete: Cascade)\n  permissao Permissao @relation(fields: [permissao_id], references: [id], onDelete: Cascade)\n\n  @@id([perfil_id, permissao_id])\n  @@map(\"perfis_permissoes\")\n}\n\n// ─── CONVITE DE USUÁRIO ───────────────────────────────────────────────────────\n\nmodel ConviteEmpresa {\n  id            String    @id @default(cuid())\n  empresa_id    String\n  email         String\n  perfil_id     String\n  token         String    @unique @default(cuid())\n  convidado_por String?\n  aceito_em     DateTime?\n  expira_em     DateTime\n  criado_em     DateTime  @default(now())\n\n  empresa   Empresa  @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  convidado Usuario? @relation(fields: [convidado_por], references: [id])\n\n  @@map(\"convites_empresa\")\n}\n\nmodel ConviteCliente {\n  id         String    @id @default(cuid())\n  empresa_id String\n  token      String    @unique @default(cuid())\n  criado_por String?\n  usado_em   DateTime?\n  cliente_id String?   @unique\n  expira_em  DateTime?\n  criado_em  DateTime  @default(now())\n\n  empresa Empresa  @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  criador Usuario? @relation(fields: [criado_por], references: [id])\n  cliente Cliente? @relation(fields: [cliente_id], references: [id])\n\n  @@map(\"convites_cliente\")\n}\n\n// ─── FASE 1: ENUMS ────────────────────────────────────────────────────────────\n\nenum TipoCliente {\n  PESSOA_FISICA\n  PESSOA_JURIDICA\n}\n\nenum StatusCliente {\n  ATIVO\n  INATIVO\n  PROSPECT\n}\n\nenum StatusProposta {\n  RASCUNHO\n  ENVIADA\n  VISUALIZADA\n  ACEITA\n  RECUSADA\n  EXPIRADA\n}\n\nenum StatusContrato {\n  RASCUNHO\n  AGUARDANDO_ASSINATURA\n  ASSINADO\n  CANCELADO\n}\n\n// ─── CLIENTES ─────────────────────────────────────────────────────────────────\n\nmodel Cliente {\n  id                 String        @id @default(cuid())\n  empresa_id         String\n  nome               String\n  tipo               TipoCliente   @default(PESSOA_JURIDICA)\n  nome_fantasia      String?\n  cpf_cnpj           String?\n  inscricao_estadual String?\n  contato_principal  String?\n  email              String?\n  telefone           String?\n  whatsapp           String?\n  cep                String?\n  logradouro         String?\n  numero             String?\n  complemento        String?\n  bairro             String?\n  cidade             String?\n  estado             String?\n  nome_fazenda       String?\n  distancia_km       Decimal?      @db.Decimal(8, 2)\n  preco_km           Decimal?      @db.Decimal(8, 2)\n  status             StatusCliente @default(ATIVO)\n  asaas_id           String?\n  criado_em          DateTime      @default(now())\n  atualizado_em      DateTime      @updatedAt\n\n  empresa                Empresa                @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  contatos               Contato[]\n  leads                  Lead[]\n  propostas              Proposta[]\n  contratos              Contrato[]\n  projetos               Projeto[]\n  tokens_portal          TokenPortal[]\n  recebiveis             Recebivel[]\n  boletos                Boleto[]\n  eventos                Evento[]\n  notas_fiscais          NotaFiscal[]\n  diagnosticos           Diagnostico[]\n  convite                ConviteCliente?\n  documentos             Documento[]\n  aplicacoes_diagnostico AplicacaoDiagnostico[]\n  assinaturas            Assinatura[]\n\n  @@map(\"clientes\")\n}\n\nmodel Contato {\n  id         String   @id @default(cuid())\n  cliente_id String\n  nome       String\n  cargo      String?\n  email      String?\n  telefone   String?\n  principal  Boolean  @default(false)\n  criado_em  DateTime @default(now())\n\n  cliente Cliente @relation(fields: [cliente_id], references: [id], onDelete: Cascade)\n\n  @@map(\"contatos\")\n}\n\n// ─── SERVIÇOS ─────────────────────────────────────────────────────────────────\n\nmodel Servico {\n  id                   String   @id @default(cuid())\n  empresa_id           String\n  plano_contas_id      String?\n  nome                 String\n  descricao            String?\n  valor_base           Decimal? @db.Decimal(10, 2)\n  ativo                Boolean  @default(true)\n  canal                String? // ARATO | CONSELHO_AGRO | CONSULTORIA\n  plano                String? // ESSENCIAL | GESTAO | PERFORMANCE | NOVO_AGRO | MESA_AGRO | CONSULTORIA_AGRO\n  tipo_cobranca        String? // ASSINATURA | PROJETO | PONTUAL\n  asaas_link_pagamento String?\n  criado_em            DateTime @default(now())\n  atualizado_em        DateTime @updatedAt\n\n  empresa         Empresa         @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  plano_contas    PlanoDeContas?  @relation(fields: [plano_contas_id], references: [id], onDelete: SetNull)\n  itens_proposta  ItemProposta[]\n  leads           Lead[]\n  assinaturas     Assinatura[]\n  campanhas_cupom CampanhaCupom[]\n\n  @@map(\"servicos\")\n}\n\n// ─── CRM ──────────────────────────────────────────────────────────────────────\n\nmodel EtapaCrm {\n  id         String   @id @default(cuid())\n  empresa_id String\n  chave      String\n  nome       String\n  cor        String   @default(\"#1B4F72\")\n  ordem      Int      @default(0)\n  criado_em  DateTime @default(now())\n\n  empresa Empresa @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  leads   Lead[]\n\n  @@unique([empresa_id, chave])\n  @@map(\"etapas_crm\")\n}\n\nmodel ComentarioCrm {\n  id         String   @id @default(cuid())\n  lead_id    String\n  usuario_id String?\n  autor_nome String\n  mensagem   String\n  criado_em  DateTime @default(now())\n\n  lead    Lead     @relation(fields: [lead_id], references: [id], onDelete: Cascade)\n  usuario Usuario? @relation(fields: [usuario_id], references: [id])\n\n  @@map(\"comentarios_crm\")\n}\n\nmodel Lead {\n  id                  String    @id @default(cuid())\n  empresa_id          String\n  cliente_id          String?\n  responsavel_id      String?\n  servico_id          String?\n  etapa_id            String?\n  nome                String\n  empresa_nome        String?\n  contato_nome        String?\n  email               String?\n  telefone            String?\n  whatsapp            String?\n  etapa_chave         String    @default(\"NOVO\")\n  valor_estimado      Decimal?  @db.Decimal(10, 2)\n  probabilidade       Int       @default(10)\n  previsao_fechamento DateTime?\n  proxima_acao        String?\n  data_proxima_acao   DateTime?\n  origem              String?\n  observacoes         String?\n  motivo_perda        String?\n  tags                String[]  @default([])\n  criado_em           DateTime  @default(now())\n  atualizado_em       DateTime  @updatedAt\n\n  empresa                  Empresa                  @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  cliente                  Cliente?                 @relation(fields: [cliente_id], references: [id])\n  responsavel              Usuario?                 @relation(fields: [responsavel_id], references: [id])\n  servico                  Servico?                 @relation(fields: [servico_id], references: [id])\n  etapa                    EtapaCrm?                @relation(fields: [etapa_id], references: [id])\n  comentarios              ComentarioCrm[]\n  propostas                Proposta[]\n  diagnostico_participante DiagnosticoParticipante?\n\n  @@map(\"leads\")\n}\n\n// ─── PROPOSTAS ────────────────────────────────────────────────────────────────\n\nmodel Proposta {\n  id                  String         @id @default(cuid())\n  empresa_id          String\n  cliente_id          String\n  lead_id             String?\n  criado_por          String?\n  responsavel_id      String?\n  titulo              String\n  objeto              String?\n  status              StatusProposta @default(RASCUNHO)\n  token_aceite        String         @unique @default(cuid())\n  introducao          String?\n  condicoes           String?\n  valor_total         Decimal        @default(0) @db.Decimal(10, 2)\n  forma_pagamento     String?\n  periodicidade       String?\n  numero_parcelas     Int?\n  primeiro_vencimento DateTime?\n  validade            DateTime?\n  contato_nome        String?\n  contato_email       String?\n  contato_telefone    String?\n  parcelas_json       Json?\n  enviado_em          DateTime?\n  visualizado_em      DateTime?\n  aceito_em           DateTime?\n  recusado_em         DateTime?\n  criado_em           DateTime       @default(now())\n  atualizado_em       DateTime       @updatedAt\n\n  empresa     Empresa        @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  cliente     Cliente        @relation(fields: [cliente_id], references: [id])\n  lead        Lead?          @relation(fields: [lead_id], references: [id])\n  criador     Usuario?       @relation(fields: [criado_por], references: [id])\n  responsavel Usuario?       @relation(\"PropostasResponsavel\", fields: [responsavel_id], references: [id])\n  itens       ItemProposta[]\n  contrato    Contrato?\n  aceite_otps AceiteOtp[]\n\n  @@map(\"propostas\")\n}\n\nmodel AceiteOtp {\n  id          String   @id @default(cuid())\n  proposta_id String\n  codigo      String\n  email       String\n  expira_em   DateTime\n  tentativas  Int      @default(0)\n  criado_em   DateTime @default(now())\n\n  proposta Proposta @relation(fields: [proposta_id], references: [id], onDelete: Cascade)\n\n  @@map(\"aceite_otp\")\n}\n\nmodel ItemProposta {\n  id             String  @id @default(cuid())\n  proposta_id    String\n  servico_id     String?\n  descricao      String\n  quantidade     Decimal @default(1) @db.Decimal(10, 3)\n  valor_unitario Decimal @db.Decimal(10, 2)\n  desconto       Decimal @default(0) @db.Decimal(5, 2)\n  ordem          Int     @default(0)\n\n  proposta Proposta @relation(fields: [proposta_id], references: [id], onDelete: Cascade)\n  servico  Servico? @relation(fields: [servico_id], references: [id])\n\n  @@map(\"itens_proposta\")\n}\n\n// ─── CONTRATOS ────────────────────────────────────────────────────────────────\n\nmodel Contrato {\n  id                      String         @id @default(cuid())\n  empresa_id              String\n  proposta_id             String?        @unique\n  cliente_id              String\n  criado_por              String?\n  responsavel_id          String?\n  numero_contrato         String?\n  tipo_contrato           String?\n  titulo                  String\n  objeto                  String?\n  status                  StatusContrato @default(RASCUNHO)\n  conteudo                String?\n  valor_total             Decimal        @default(0) @db.Decimal(10, 2)\n  forma_pagamento         String?\n  periodicidade           String?\n  numero_parcelas         Int?\n  primeiro_vencimento     DateTime?\n  dia_vencimento          Int?\n  parcelas_json           Json?\n  indice_reajuste         String?\n  periodicidade_reajuste  String?\n  renovacao_automatica    Boolean        @default(false)\n  gerar_projeto           Boolean        @default(false)\n  gerar_financeiro        Boolean        @default(true)\n  cliente_nome            String?\n  cliente_cpf_cnpj        String?\n  cliente_contato_nome    String?\n  cliente_contato_email   String?\n  cliente_contato_tel     String?\n  data_emissao            DateTime?\n  data_inicio             DateTime?\n  data_fim                DateTime?\n  assinado_em             DateTime?\n  anexo_url               String?\n  authentique_id          String?\n  authentique_url         String?\n  pdf_assinado_url        String?\n  juros_ao_mes_percentual Decimal?       @db.Decimal(5, 2)\n  multa_percentual        Decimal?       @db.Decimal(5, 2)\n  probono_arato           Boolean        @default(false)\n  probono_versao          String?\n  probono_meses           Int?\n  criado_em               DateTime       @default(now())\n  atualizado_em           DateTime       @updatedAt\n\n  empresa       Empresa      @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  proposta      Proposta?    @relation(fields: [proposta_id], references: [id])\n  cliente       Cliente      @relation(fields: [cliente_id], references: [id])\n  criador       Usuario?     @relation(fields: [criado_por], references: [id])\n  responsavel   Usuario?     @relation(\"ContratosResponsavel\", fields: [responsavel_id], references: [id])\n  projeto       Projeto?\n  recebiveis    Recebivel[]\n  eventos       Evento[]\n  notas_fiscais NotaFiscal[]\n  documentos    Documento[]\n\n  @@map(\"contratos\")\n}\n\n// ─── FASE 2: ENUMS ────────────────────────────────────────────────────────────\n\nenum StatusProjeto {\n  PLANEJAMENTO\n  EM_ANDAMENTO\n  CONCLUIDO\n  CANCELADO\n}\n\nenum StatusEtapa {\n  PENDENTE\n  EM_ANDAMENTO\n  CONCLUIDA\n  CANCELADA\n}\n\nenum StatusTarefa {\n  PENDENTE\n  EM_ANDAMENTO\n  CONCLUIDA\n  CANCELADA\n}\n\nenum PrioridadeTarefa {\n  BAIXA\n  MEDIA\n  ALTA\n  URGENTE\n}\n\nenum StatusAprovacao {\n  PENDENTE\n  APROVADO\n  REPROVADO\n}\n\nenum CategoriaDocumento {\n  CONTRATO\n  PROPOSTA\n  PROJETO\n  FINANCEIRO\n  INTERNO\n  OUTROS\n}\n\n// ─── PROJETOS ─────────────────────────────────────────────────────────────────\n\nmodel Projeto {\n  id             String        @id @default(cuid())\n  empresa_id     String\n  contrato_id    String?       @unique\n  cliente_id     String?\n  interno        Boolean       @default(false)\n  criado_por     String?\n  titulo         String\n  descricao      String?\n  status         StatusProjeto @default(PLANEJAMENTO)\n  data_inicio    DateTime?\n  data_fim       DateTime?\n  e_centro_custo Boolean       @default(false)\n  criado_em      DateTime      @default(now())\n  atualizado_em  DateTime      @updatedAt\n\n  empresa                Empresa                @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  contrato               Contrato?              @relation(fields: [contrato_id], references: [id])\n  cliente                Cliente?               @relation(fields: [cliente_id], references: [id])\n  criador                Usuario?               @relation(fields: [criado_por], references: [id])\n  etapas                 Etapa[]\n  tarefas                Tarefa[]\n  documentos             Documento[]\n  eventos                Evento[]\n  diagnosticos           Diagnostico[]\n  aplicacoes_diagnostico AplicacaoDiagnostico[]\n  centro_custo           CentroCusto?\n\n  @@map(\"projetos\")\n}\n\nmodel Etapa {\n  id            String      @id @default(cuid())\n  projeto_id    String\n  titulo        String\n  descricao     String?\n  status        StatusEtapa @default(PENDENTE)\n  ordem         Int         @default(0)\n  data_inicio   DateTime?\n  data_fim      DateTime?\n  criado_em     DateTime    @default(now())\n  atualizado_em DateTime    @updatedAt\n\n  projeto Projeto  @relation(fields: [projeto_id], references: [id], onDelete: Cascade)\n  tarefas Tarefa[]\n\n  @@map(\"etapas\")\n}\n\nmodel Tarefa {\n  id             String           @id @default(cuid())\n  etapa_id       String\n  projeto_id     String\n  responsavel_id String?\n  titulo         String\n  descricao      String?\n  status         StatusTarefa     @default(PENDENTE)\n  prioridade     PrioridadeTarefa @default(MEDIA)\n  ordem          Int              @default(0)\n  data_prazo     DateTime?\n  concluida_em   DateTime?\n  criado_em      DateTime         @default(now())\n  atualizado_em  DateTime         @updatedAt\n\n  etapa       Etapa    @relation(fields: [etapa_id], references: [id], onDelete: Cascade)\n  projeto     Projeto  @relation(fields: [projeto_id], references: [id], onDelete: Cascade)\n  responsavel Usuario? @relation(fields: [responsavel_id], references: [id])\n\n  comentarios  ComentarioTarefa[]\n  anexos       AnexoTarefa[]\n  atividades   AtividadeTarefa[]\n  aprovacoes   AprovacaoTarefa[]\n  checklist    ItemChecklist[]\n  etiquetas    TarefaEtiqueta[]\n  responsaveis TarefaResponsavel[]\n\n  @@map(\"tarefas\")\n}\n\nmodel TarefaResponsavel {\n  tarefa_id  String\n  usuario_id String\n\n  tarefa  Tarefa  @relation(fields: [tarefa_id], references: [id], onDelete: Cascade)\n  usuario Usuario @relation(fields: [usuario_id], references: [id], onDelete: Cascade)\n\n  @@id([tarefa_id, usuario_id])\n  @@map(\"tarefas_responsaveis\")\n}\n\nmodel ComentarioTarefa {\n  id            String   @id @default(cuid())\n  tarefa_id     String\n  autor_id      String?\n  conteudo      String\n  criado_em     DateTime @default(now())\n  atualizado_em DateTime @updatedAt\n\n  tarefa Tarefa   @relation(fields: [tarefa_id], references: [id], onDelete: Cascade)\n  autor  Usuario? @relation(fields: [autor_id], references: [id])\n\n  @@map(\"comentarios_tarefa\")\n}\n\nmodel AnexoTarefa {\n  id              String   @id @default(cuid())\n  tarefa_id       String\n  criado_por      String?\n  nome            String\n  arquivo_url     String\n  arquivo_tamanho Int      @default(0)\n  mime_type       String   @default(\"application/octet-stream\")\n  criado_em       DateTime @default(now())\n\n  tarefa  Tarefa   @relation(fields: [tarefa_id], references: [id], onDelete: Cascade)\n  criador Usuario? @relation(fields: [criado_por], references: [id])\n\n  @@map(\"anexos_tarefa\")\n}\n\nmodel AtividadeTarefa {\n  id        String   @id @default(cuid())\n  tarefa_id String\n  autor_id  String?\n  descricao String\n  criado_em DateTime @default(now())\n\n  tarefa Tarefa   @relation(fields: [tarefa_id], references: [id], onDelete: Cascade)\n  autor  Usuario? @relation(fields: [autor_id], references: [id])\n\n  @@map(\"atividades_tarefa\")\n}\n\nmodel AprovacaoTarefa {\n  id             String          @id @default(cuid())\n  tarefa_id      String\n  solicitante_id String?\n  aprovador_id   String?\n  status         StatusAprovacao @default(PENDENTE)\n  comentario     String?\n  criado_em      DateTime        @default(now())\n  decidido_em    DateTime?\n\n  tarefa      Tarefa   @relation(fields: [tarefa_id], references: [id], onDelete: Cascade)\n  solicitante Usuario? @relation(\"AprovacaoSolicitante\", fields: [solicitante_id], references: [id])\n  aprovador   Usuario? @relation(\"AprovacaoAprovador\", fields: [aprovador_id], references: [id])\n\n  @@map(\"aprovacoes_tarefa\")\n}\n\nmodel ItemChecklist {\n  id        String   @id @default(cuid())\n  tarefa_id String\n  texto     String\n  concluido Boolean  @default(false)\n  ordem     Int      @default(0)\n  criado_em DateTime @default(now())\n\n  tarefa Tarefa @relation(fields: [tarefa_id], references: [id], onDelete: Cascade)\n\n  @@map(\"checklist_tarefa\")\n}\n\nmodel EtiquetaTarefa {\n  id         String @id @default(cuid())\n  empresa_id String\n  nome       String\n  cor        String @default(\"#64748B\")\n\n  empresa Empresa          @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  tarefas TarefaEtiqueta[]\n\n  @@map(\"etiquetas_tarefa\")\n}\n\nmodel TarefaEtiqueta {\n  tarefa_id   String\n  etiqueta_id String\n\n  tarefa   Tarefa         @relation(fields: [tarefa_id], references: [id], onDelete: Cascade)\n  etiqueta EtiquetaTarefa @relation(fields: [etiqueta_id], references: [id], onDelete: Cascade)\n\n  @@id([tarefa_id, etiqueta_id])\n  @@map(\"tarefas_etiquetas\")\n}\n\n// ─── DOCUMENTOS ───────────────────────────────────────────────────────────────\n\nmodel PastaDocumento {\n  id            String   @id @default(cuid())\n  empresa_id    String\n  nome          String\n  descricao     String?\n  parent_id     String?\n  criado_por    String?\n  criado_em     DateTime @default(now())\n  atualizado_em DateTime @updatedAt\n\n  empresa    Empresa          @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  parent     PastaDocumento?  @relation(\"PastaHierarquia\", fields: [parent_id], references: [id], onDelete: Cascade)\n  filhos     PastaDocumento[] @relation(\"PastaHierarquia\")\n  documentos Documento[]\n\n  @@map(\"pastas_documento\")\n}\n\nmodel Documento {\n  id              String             @id @default(cuid())\n  empresa_id      String\n  projeto_id      String?\n  cliente_id      String?\n  contrato_id     String?\n  pasta_id        String?\n  criado_por      String?\n  titulo          String\n  descricao       String?\n  categoria       CategoriaDocumento @default(INTERNO)\n  arquivo_url     String\n  arquivo_nome    String\n  arquivo_tamanho Int                @default(0)\n  mime_type       String             @default(\"application/octet-stream\")\n  criado_em       DateTime           @default(now())\n\n  empresa  Empresa         @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  projeto  Projeto?        @relation(fields: [projeto_id], references: [id])\n  cliente  Cliente?        @relation(fields: [cliente_id], references: [id])\n  contrato Contrato?       @relation(fields: [contrato_id], references: [id])\n  pasta    PastaDocumento? @relation(fields: [pasta_id], references: [id])\n  criador  Usuario?        @relation(fields: [criado_por], references: [id])\n\n  @@map(\"documentos\")\n}\n\n// ─── FASE 3: ENUMS ────────────────────────────────────────────────────────────\n\nenum TipoConta {\n  CORRENTE\n  POUPANCA\n  CAIXA\n  INVESTIMENTO\n}\n\nenum StatusRecebivel {\n  PENDENTE\n  PARCIAL\n  PAGO\n  VENCIDO\n  CANCELADO\n  RENEGOCIADO\n}\n\nenum StatusContaPagar {\n  PENDENTE\n  PARCIAL\n  PAGO\n  VENCIDO\n  CANCELADO\n}\n\nenum TipoPlanoContas {\n  RECEITA\n  CUSTO\n  DESPESA\n  INVESTIMENTO\n  TESOURARIA\n}\n\n// ─── PLANO DE CONTAS ──────────────────────────────────────────────────────────\n\nmodel PlanoDeContas {\n  id                String          @id @default(cuid())\n  empresa_id        String\n  parent_id         String?\n  nome              String\n  tipo              TipoPlanoContas\n  codigo            String?\n  aceita_lancamento Boolean         @default(true)\n  ativo             Boolean         @default(true)\n  criado_em         DateTime        @default(now())\n\n  empresa      Empresa         @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  parent       PlanoDeContas?  @relation(\"PlanoHierarquia\", fields: [parent_id], references: [id])\n  filhos       PlanoDeContas[] @relation(\"PlanoHierarquia\")\n  recebiveis   Recebivel[]\n  contas_pagar ContaPagar[]\n  servicos     Servico[]\n\n  @@map(\"plano_de_contas\")\n}\n\n// ─── BANCOS ───────────────────────────────────────────────────────────────────\n\nmodel Banco {\n  id     String @id @default(cuid())\n  codigo String @unique\n  nome   String\n  sigla  String\n\n  contas_bancarias ContaBancaria[]\n\n  @@map(\"bancos\")\n}\n\n// ─── CONTAS BANCÁRIAS ─────────────────────────────────────────────────────────\n\nmodel ContaBancaria {\n  id            String    @id @default(cuid())\n  empresa_id    String\n  nome          String\n  banco_id      String?\n  banco         String?\n  agencia       String?\n  conta         String?\n  digito        String?\n  pix_chave     String?\n  tipo          TipoConta @default(CORRENTE)\n  saldo_inicial Decimal   @default(0) @db.Decimal(12, 2)\n  ativo         Boolean   @default(true)\n  criado_em     DateTime  @default(now())\n  atualizado_em DateTime  @updatedAt\n\n  empresa                Empresa                   @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  banco_ref              Banco?                    @relation(fields: [banco_id], references: [id])\n  recebiveis             Recebivel[]\n  contas_pagar           ContaPagar[]\n  transferencias_origem  TransferenciaTesouraria[] @relation(\"TransferenciaOrigem\")\n  transferencias_destino TransferenciaTesouraria[] @relation(\"TransferenciaDestino\")\n\n  @@map(\"contas_bancarias\")\n}\n\nmodel TransferenciaTesouraria {\n  id               String   @id @default(cuid())\n  empresa_id       String\n  conta_origem_id  String\n  conta_destino_id String\n  valor            Decimal  @db.Decimal(12, 2)\n  data             DateTime\n  descricao        String?\n  criado_em        DateTime @default(now())\n\n  empresa       Empresa       @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  conta_origem  ContaBancaria @relation(\"TransferenciaOrigem\", fields: [conta_origem_id], references: [id])\n  conta_destino ContaBancaria @relation(\"TransferenciaDestino\", fields: [conta_destino_id], references: [id])\n\n  @@map(\"transferencias_tesouraria\")\n}\n\n// ─── CENTROS DE CUSTO ────────────────────────────────────────────────────────\n\nmodel CentroCusto {\n  id            String   @id @default(cuid())\n  empresa_id    String\n  nome          String\n  codigo        String?\n  descricao     String?\n  ativo         Boolean  @default(true)\n  projeto_id    String?  @unique\n  criado_em     DateTime @default(now())\n  atualizado_em DateTime @updatedAt\n\n  empresa      Empresa      @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  projeto      Projeto?     @relation(fields: [projeto_id], references: [id], onDelete: Cascade)\n  recebiveis   Recebivel[]\n  contas_pagar ContaPagar[]\n\n  @@map(\"centros_custo\")\n}\n\n// ─── RECEBÍVEIS ───────────────────────────────────────────────────────────────\n\nmodel Recebivel {\n  id                   String          @id @default(cuid())\n  empresa_id           String\n  cliente_id           String?\n  contrato_id          String?\n  plano_contas_id      String?\n  conta_bancaria_id    String?\n  criado_por           String?\n  descricao            String\n  valor                Decimal         @db.Decimal(10, 2)\n  data_vencimento      DateTime\n  status               StatusRecebivel @default(PENDENTE)\n  data_pagamento       DateTime?\n  valor_pago           Decimal?        @db.Decimal(10, 2)\n  forma_pagamento      String?\n  numero_parcela       Int?\n  total_parcelas       Int?\n  observacoes          String?\n  juros_valor          Decimal?        @db.Decimal(10, 2)\n  multa_valor          Decimal?        @db.Decimal(10, 2)\n  desconto_valor       Decimal?        @db.Decimal(10, 2)\n  recebivel_origem_id  String?\n  centro_custo_id      String?\n  asaas_payment_id     String?\n  asaas_invoice_url    String?\n  asaas_pix_copia_cola String?\n  asaas_boleto_url     String?\n  asaas_status         String?\n  criado_em            DateTime        @default(now())\n  atualizado_em        DateTime        @updatedAt\n\n  empresa        Empresa        @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  cliente        Cliente?       @relation(fields: [cliente_id], references: [id])\n  contrato       Contrato?      @relation(fields: [contrato_id], references: [id])\n  plano_contas   PlanoDeContas? @relation(fields: [plano_contas_id], references: [id])\n  conta_bancaria ContaBancaria? @relation(fields: [conta_bancaria_id], references: [id])\n  criador        Usuario?       @relation(\"RecebiveisCriados\", fields: [criado_por], references: [id])\n  centro_custo   CentroCusto?   @relation(fields: [centro_custo_id], references: [id])\n  boleto         Boleto?\n  nota_fiscal    NotaFiscal?\n\n  @@map(\"recebiveis\")\n}\n\n// ─── CONTAS A PAGAR ───────────────────────────────────────────────────────────\n\nmodel ContaPagar {\n  id                String           @id @default(cuid())\n  empresa_id        String\n  plano_contas_id   String?\n  conta_bancaria_id String?\n  fornecedor_id     String?\n  criado_por        String?\n  descricao         String\n  fornecedor        String?\n  valor             Decimal          @db.Decimal(10, 2)\n  data_vencimento   DateTime\n  status            StatusContaPagar @default(PENDENTE)\n  data_pagamento    DateTime?\n  valor_pago        Decimal?         @db.Decimal(10, 2)\n  forma_pagamento   String?\n  observacoes       String?\n  centro_custo_id   String?\n  criado_em         DateTime         @default(now())\n  atualizado_em     DateTime         @updatedAt\n\n  empresa        Empresa        @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  plano_contas   PlanoDeContas? @relation(fields: [plano_contas_id], references: [id])\n  conta_bancaria ContaBancaria? @relation(fields: [conta_bancaria_id], references: [id])\n  criador        Usuario?       @relation(\"ContasPagarCriadas\", fields: [criado_por], references: [id])\n  centro_custo   CentroCusto?   @relation(fields: [centro_custo_id], references: [id])\n  fornecedor_rel Fornecedor?    @relation(fields: [fornecedor_id], references: [id])\n\n  @@map(\"contas_pagar\")\n}\n\n// ─── FORNECEDORES ─────────────────────────────────────────────────────────────\n\nmodel Fornecedor {\n  id             String   @id @default(cuid())\n  empresa_id     String\n  nome           String\n  cnpj_cpf       String?\n  email          String?\n  telefone       String?\n  whatsapp       String?\n  // Contato\n  nome_contato   String?\n  cargo_contato  String?\n  // Endereço\n  cep            String?\n  logradouro     String?\n  numero         String?\n  complemento    String?\n  bairro         String?\n  cidade         String?\n  estado         String?\n  // Dados bancários\n  banco          String?\n  agencia        String?\n  conta          String?\n  tipo_conta     String?\n  // Pix\n  chave_pix      String?\n  tipo_chave_pix String?\n  // Geral\n  observacoes    String?\n  ativo          Boolean  @default(true)\n  criado_em      DateTime @default(now())\n  atualizado_em  DateTime @updatedAt\n\n  empresa      Empresa      @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  contas_pagar ContaPagar[]\n\n  @@map(\"fornecedores\")\n}\n\n// ─── FASE 4: ENUMS ────────────────────────────────────────────────────────────\n\nenum TipoModelo {\n  CONTRATO\n  PROPOSTA\n  RECIBO\n  GENERICO\n}\n\n// ─── MODELOS DE DOCUMENTO ─────────────────────────────────────────────────────\n\nmodel ModeloDocumento {\n  id            String     @id @default(cuid())\n  empresa_id    String\n  nome          String\n  tipo          TipoModelo\n  conteudo      String     @default(\"\")\n  ativo         Boolean    @default(true)\n  criado_em     DateTime   @default(now())\n  atualizado_em DateTime   @updatedAt\n\n  empresa Empresa @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n\n  @@map(\"modelos_documento\")\n}\n\n// ─── FASE 5: AGENDA ───────────────────────────────────────────────────────────\n\nmodel Evento {\n  id               String    @id @default(cuid())\n  empresa_id       String\n  responsavel_id   String?\n  cliente_id       String?\n  contrato_id      String?\n  projeto_id       String?\n  titulo           String\n  descricao        String?\n  inicio           DateTime\n  fim              DateTime?\n  dia_todo         Boolean   @default(false)\n  lembrete_minutos Int?\n  lembrete_em      DateTime?\n  lembrete_enviado Boolean   @default(false)\n  criado_em        DateTime  @default(now())\n  atualizado_em    DateTime  @updatedAt\n\n  empresa     Empresa   @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  responsavel Usuario?  @relation(\"EventosResponsavel\", fields: [responsavel_id], references: [id])\n  cliente     Cliente?  @relation(fields: [cliente_id], references: [id])\n  contrato    Contrato? @relation(fields: [contrato_id], references: [id])\n  projeto     Projeto?  @relation(fields: [projeto_id], references: [id])\n\n  @@map(\"eventos\")\n}\n\n// ─── FASE 5: AUDITORIA ────────────────────────────────────────────────────────\n\nmodel RegistroAuditoria {\n  id           String   @id @default(cuid())\n  empresa_id   String\n  usuario_id   String?\n  usuario_nome String?\n  recurso      String\n  acao         String\n  registro_id  String?\n  detalhes     Json?\n  criado_em    DateTime @default(now())\n\n  empresa Empresa @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n\n  @@map(\"registros_auditoria\")\n}\n\n// ─── FASE 6: NOTIFICAÇÕES ─────────────────────────────────────────────────────\n\nmodel Notificacao {\n  id         String    @id @default(cuid())\n  empresa_id String\n  usuario_id String?\n  tipo       String\n  titulo     String\n  mensagem   String?\n  lida       Boolean   @default(false)\n  lida_em    DateTime?\n  url        String?\n  criado_em  DateTime  @default(now())\n\n  empresa Empresa @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n\n  @@map(\"notificacoes\")\n}\n\n// ─── FASE 7: FATURAMENTO ──────────────────────────────────────────────────────\n\nenum StatusNota {\n  PENDENTE\n  EMITIDA\n  PAGA\n  CANCELADA\n}\n\nmodel NotaFiscal {\n  id              String     @id @default(cuid())\n  empresa_id      String\n  cliente_id      String\n  contrato_id     String?\n  criado_por      String?\n  numero          String?\n  competencia     DateTime\n  valor           Decimal    @db.Decimal(10, 2)\n  descricao       String\n  status          StatusNota @default(PENDENTE)\n  data_emissao    DateTime?\n  data_vencimento DateTime?\n  observacoes     String?\n  criado_em       DateTime   @default(now())\n  atualizado_em   DateTime   @updatedAt\n\n  recebivel_id     String?   @unique\n  nfsio_id         String?\n  asaas_invoice_id String?\n  nfse_provider    String? // 'nfsio' | 'asaas'\n  numero_nfse      String?\n  codigo_servico   String?\n  aliquota_iss     Decimal?  @db.Decimal(5, 2)\n  pdf_url          String?\n  xml_url          String?\n  email_enviado    Boolean   @default(false)\n  email_enviado_em DateTime?\n\n  empresa   Empresa    @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  cliente   Cliente    @relation(fields: [cliente_id], references: [id])\n  contrato  Contrato?  @relation(fields: [contrato_id], references: [id])\n  recebivel Recebivel? @relation(fields: [recebivel_id], references: [id])\n\n  @@map(\"notas_fiscais\")\n}\n\nmodel Boleto {\n  id                String   @id @default(cuid())\n  empresa_id        String\n  recebivel_id      String   @unique\n  cliente_id        String?\n  asaas_id          String?\n  asaas_customer_id String?\n  status            String   @default(\"PENDENTE\")\n  valor             Decimal  @db.Decimal(12, 2)\n  vencimento        DateTime\n  linha_digitavel   String?\n  codigo_barras     String?\n  url_boleto        String?\n  url_fatura        String?\n  nosso_numero      String?\n  criado_em         DateTime @default(now())\n  atualizado_em     DateTime @updatedAt\n\n  empresa   Empresa   @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  recebivel Recebivel @relation(fields: [recebivel_id], references: [id], onDelete: Cascade)\n  cliente   Cliente?  @relation(fields: [cliente_id], references: [id])\n\n  @@map(\"boletos\")\n}\n\n// ─── FASE 8: DIAGRAMAS & DIAGNÓSTICOS ────────────────────────────────────────\n\nenum TipoDiagnostico {\n  SWOT\n  CANVAS\n  CINCO_W_DOIS_H\n  ORGANOGRAMA\n  MAPA_PROCESSO\n  GANTT\n  MAPA_MENTAL\n}\n\nmodel Diagnostico {\n  id            String          @id @default(cuid())\n  empresa_id    String\n  cliente_id    String?\n  projeto_id    String?\n  criado_por    String?\n  tipo          TipoDiagnostico\n  titulo        String\n  conteudo      Json            @default(\"{}\")\n  criado_em     DateTime        @default(now())\n  atualizado_em DateTime        @updatedAt\n\n  empresa Empresa  @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  cliente Cliente? @relation(fields: [cliente_id], references: [id])\n  projeto Projeto? @relation(fields: [projeto_id], references: [id])\n\n  @@map(\"diagnosticos\")\n}\n\n// ─── PORTAL DO CLIENTE ────────────────────────────────────────────────────────\n\nmodel TokenPortal {\n  id         String    @id @default(cuid())\n  cliente_id String\n  token      String    @unique @default(cuid())\n  email      String\n  expira_em  DateTime\n  usado_em   DateTime?\n  criado_em  DateTime  @default(now())\n\n  cliente Cliente @relation(fields: [cliente_id], references: [id], onDelete: Cascade)\n\n  @@map(\"tokens_portal\")\n}\n\n// ─── DIAGNÓSTICO DE COLETA (QUESTIONÁRIO PERFIL DO CLIENTE) ───────────────────\n\nenum MomentoDiagnostico {\n  PONTO_A\n  PONTO_B\n  PONTO_C\n}\n\nenum StatusAplicacaoDiagnostico {\n  PENDENTE\n  ENVIADO\n  RESPONDIDO\n}\n\nmodel AplicacaoDiagnostico {\n  id            String                     @id @default(cuid())\n  empresa_id    String\n  projeto_id    String\n  cliente_id    String?\n  criado_por    String?\n  momento       MomentoDiagnostico\n  status        StatusAplicacaoDiagnostico @default(PENDENTE)\n  token         String                     @unique @default(cuid())\n  respostas     Json?\n  enviado_em    DateTime?\n  respondido_em DateTime?\n  criado_em     DateTime                   @default(now())\n  atualizado_em DateTime                   @updatedAt\n\n  empresa Empresa  @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  projeto Projeto  @relation(fields: [projeto_id], references: [id], onDelete: Cascade)\n  cliente Cliente? @relation(fields: [cliente_id], references: [id])\n\n  @@unique([projeto_id, momento])\n  @@map(\"aplicacoes_diagnostico\")\n}\n\n// ─── FUNIL DE DIAGNÓSTICO PÚBLICO (HOTPAGE) ───────────────────────────────────\n\nmodel CampanhaDiagnostico {\n  id            String   @id @default(cuid())\n  empresa_id    String\n  slug          String   @unique\n  titulo        String   @default(\"Diagnóstico Empresarial\")\n  subtitulo     String?\n  video_youtube String?\n  url_checkout  String?\n  ativo         Boolean  @default(true)\n  criado_em     DateTime @default(now())\n  atualizado_em DateTime @updatedAt\n\n  empresa       Empresa                   @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  participantes DiagnosticoParticipante[]\n\n  @@map(\"campanhas_diagnostico\")\n}\n\nmodel DiagnosticoParticipante {\n  id                 String    @id @default(cuid())\n  campanha_id        String\n  lead_id            String?   @unique\n  nome               String\n  cpf_cnpj           String\n  celular            String\n  email              String\n  celular_verificado Boolean   @default(false)\n  otp_code           String?\n  otp_expira_em      DateTime?\n  respostas          Json?\n  pontuacao          Int?\n  email_enviado      Boolean   @default(false)\n  criado_em          DateTime  @default(now())\n\n  campanha CampanhaDiagnostico @relation(fields: [campanha_id], references: [id], onDelete: Cascade)\n  lead     Lead?               @relation(fields: [lead_id], references: [id])\n\n  @@map(\"diagnostico_participantes\")\n}\n\n// ─── DIAGNÓSTICO AGRO — TEMPLATES ────────────────────────────────────────────\n\nmodel DiagnosticoTemplate {\n  id                  String   @id @default(cuid())\n  empresa_id          String\n  cultura             String // soja | milho | algodao | cana | gado | outro\n  nivel               String // CRITICO | ATENCAO | BOM | EXCELENTE\n  titulo              String?\n  texto_receita       String?\n  texto_custos        String?\n  texto_caixa         String?\n  texto_recomendacoes String?\n  parametros_dre      Json     @default(\"{}\")\n  criado_em           DateTime @default(now())\n  atualizado_em       DateTime @updatedAt\n\n  empresa Empresa @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n\n  @@unique([empresa_id, cultura, nivel])\n  @@map(\"diagnostico_templates\")\n}\n\n// ─── CAMPANHAS DE CUPOM DE DESCONTO ─────────────────────────────────────────\n\nenum TipoDesconto {\n  PERCENTUAL\n  FIXO\n}\n\nmodel CampanhaCupom {\n  id             String       @id @default(cuid())\n  empresa_id     String\n  servico_id     String? // serviço ao qual o cupom se aplica (null = qualquer)\n  nome           String\n  codigo         String\n  tipo_desconto  TipoDesconto @default(PERCENTUAL)\n  valor_desconto Decimal      @db.Decimal(10, 2)\n  ativo          Boolean      @default(true)\n  validade_ate   DateTime?\n  usos_maximos   Int?\n  usos_count     Int          @default(0)\n  criado_em      DateTime     @default(now())\n  atualizado_em  DateTime     @updatedAt\n\n  empresa Empresa  @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  servico Servico? @relation(fields: [servico_id], references: [id])\n\n  @@unique([empresa_id, codigo])\n  @@map(\"campanhas_cupom\")\n}\n\n// ─── ASSINATURAS (Arato SaaS, O Conselho Agro, Consultoria recorrente) ────────\n\nmodel Assinatura {\n  id                    String    @id @default(cuid())\n  empresa_id            String\n  cliente_id            String?\n  servico_id            String?\n  nome_cliente          String\n  email_cliente         String?\n  telefone_cliente      String?\n  canal                 String // ARATO | CONSELHO_AGRO | CONSULTORIA\n  plano                 String? // ESSENCIAL | GESTAO | PERFORMANCE | NOVO_AGRO | MESA_AGRO | CONSULTORIA_AGRO\n  valor                 Decimal   @db.Decimal(10, 2)\n  ciclo                 String    @default(\"MONTHLY\") // MONTHLY | YEARLY | WEEKLY\n  status                String    @default(\"ATIVA\") // ATIVA | PAUSADA | CANCELADA | INADIMPLENTE | TRIAL\n  asaas_subscription_id String?\n  asaas_customer_id     String?\n  proximo_vencimento    DateTime?\n  data_inicio           DateTime  @default(now())\n  data_cancelamento     DateTime?\n  motivo_cancelamento   String?\n  observacoes           String?\n  criado_em             DateTime  @default(now())\n  atualizado_em         DateTime  @updatedAt\n\n  empresa Empresa  @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  cliente Cliente? @relation(fields: [cliente_id], references: [id])\n  servico Servico? @relation(fields: [servico_id], references: [id])\n\n  @@map(\"assinaturas\")\n}\n\nmodel Reembolso {\n  id         String   @id @default(cuid())\n  empresa_id String\n  periodo    String // \"2026-08\"\n  descricao  String?\n  status     String   @default(\"ABERTO\") // ABERTO | PAGO\n  total      Decimal  @default(0) @db.Decimal(10, 2)\n  criado_em  DateTime @default(now())\n\n  empresa Empresa         @relation(fields: [empresa_id], references: [id], onDelete: Cascade)\n  itens   ReembolsoItem[]\n\n  @@index([empresa_id])\n  @@map(\"reembolsos\")\n}\n\nmodel ReembolsoItem {\n  id           String   @id @default(cuid())\n  reembolso_id String\n  tipo         String // DESLOCAMENTO | REFEICAO | HOTEL | PEDAGIO\n  data         DateTime\n  descricao    String\n  valor        Decimal  @db.Decimal(10, 2)\n  km           Decimal? @db.Decimal(8, 2)\n  valor_km     Decimal? @db.Decimal(8, 2)\n  clientes_ids String[] @default([])\n  criado_em    DateTime @default(now())\n\n  reembolso Reembolso @relation(fields: [reembolso_id], references: [id], onDelete: Cascade)\n\n  @@index([reembolso_id])\n  @@map(\"reembolso_itens\")\n}\n"
}

